"""Explain unsupported fallbacks, path priority and compare-to-try conversion."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1605': ('도구가 고장 나서 작업에 실패한 것과 필요한 도구 자체가 없는 것은 달라요. 지원하지 않는 연산의 표시를 정상적인 실패 답으로 읽으면 안 돼요.', '지원 누락의 빌드 진단과 실행 중 조건 실패를 구별합니다.', 'typed #error → 전처리 오류, generic not_implemented → 미제공 함수 호출 가능, 정상 try의 false → 비교 실패를 세 칸으로 나누세요.', ['조건부 원자 함수의 false는 제공되는 연산을 실행했지만 비교 조건이 맞지 않았다는 뜻일 수 있어요. 반면 지원 누락은 필요한 연산을 구현할 기반이나 경로가 없다는 다른 상황이에요.', '자료형별 fallback 생성기는 arch 경로와 변환 경로가 없고 템플릿도 없으면 #error Unable to define을 출력할 수 있어요. #error는 그 갈래가 선택됐을 때 전처리 오류를 내는 지시문이에요.', 'generic 교체 생성기의 누락 갈래는 extern void raw_이름_not_implemented(void)라는 선언과 그 함수를 부르는 매크로를 출력해요. extern 선언은 함수가 따로 있다고 알릴 뿐 구현 본문을 만들지는 않아요.', '실제로 그 호출을 사용했는데 구현이 없다면 연결 단계에서 함수를 찾지 못하는 진단이 날 수 있어요. 반환값이 필요한 문맥에서는 타입 때문에 더 이른 오류가 날 수도 있어요. 언제나 안전하게 false를 반환하는 함수가 아니에요.', '전처리는 #if 같은 조건을 고르는 단계이고, 연결은 필요한 함수·코드를 모아 실행 결과물을 만드는 단계예요. typed의 #error와 generic의 미제공 함수 호출은 진단이 생기는 방법이 달라요.', '그러므로 먼저 지원되는 arch 이름과 선택된 경로를 확인해야 해요. 한 CPU의 지원 경로가 잘 동작했다고 다른 CPU의 누락 경로까지 지원한다고 말할 수 없어요. 정상 비교 실패와 구현 누락을 같은 실패로 처리하지 마세요.'], [('generic not_implemented 경로를 안전하게 false를 반환하는 API로 사용해도 되나요?', ['네. 미구현이면 항상 false를 돌려줘요', '아니요. 구현이 없는 함수의 선언·호출로 이어질 수 있어요'], '정답은 두 번째예요. 출력은 void 함수 선언과 호출이에요. 정상 비교 실패의 bool 반환과 다르며, 지원과 빌드 가능성을 확인해야 해요.'), ('typed #error와 generic extern 누락 호출은 같은 진단 방식인가요?', ['아니요. 전처리 오류와 함수 구현을 찾지 못하는 문제는 단계가 달라요', '네. 둘 다 정상적으로 실행해서 실패 값을 반환해요'], '정답은 첫 번째예요. #error는 선택된 전처리 갈래에서 오류를 내요. extern은 선언만 하므로 실제 사용과 구현 제공에 따라 컴파일·연결 문제를 확인해야 해요.')]), 'os1606': ('정확히 필요한 도구가 있으면 먼저 쓰고, 없으면 다른 도구를 보강하거나 더 강한 도구를 빌려요. 여러 후보가 있어도 고르는 순서는 정해져 있어요.', 'generic 교체의 직접·보강·재사용 경로 우선순위를 이해합니다.', '정확한 arch 형태 → 허용된 relaxed 보강 → 기본 full 재사용 → 지원 누락의 순서를 그리세요.', ['gen_xchg_order_fallback은 교체 이름과 순서 이름을 받아 C 선택문을 출력해요. 예를 들어 cmpxchg와 _acquire를 받으면 필요한 이름은 cmpxchg_acquire예요.', '첫 #if는 정확히 같은 순서의 arch 이름이 정의됐는지 확인해요. 있으면 raw 이름을 그 arch 이름에 바로 연결해요. exact는 이처럼 요청한 이름과 순서가 맞는다는 뜻이에요.', '요청이 _relaxed가 아니라면 다음 후보는 arch의 relaxed 형태예요. 이 경우 __atomic_op 계열 도우미로 필요한 순서를 보강해요. 기본 full 요청에서는 _fence라는 도우미 이름을 사용해요.', '순서 꼬리표가 있는 요청이면 기본 full arch 연산을 쓰는 후보도 만들어요. 앞의 경로들이 없을 때 더 강한 기본 연산으로 요구를 충족하는 방법이에요. 같은 조건에서 직접 형태가 있으면 첫 경로가 우선해요.', '어느 후보도 지원되지 않으면 not_implemented 선언·호출을 출력해요. 이 과정은 generic 매크로의 경로이고 자료형별 함수 템플릿과 글자 그대로 같은 구현은 아니에요.', 'cmpxchg128이라는 이름을 만들었다고 CPU에 128비트 명령이 새로 생기지는 않아요. API의 폭, 아키텍처 지원, 실제 구현을 확인해야 해요. 생성 목록과 하드웨어에서 실제 실행한 범위는 별도로 기록하세요.'], [('같은 order의 arch 정의와 relaxed 정의가 모두 있으면 어느 쪽이 먼저인가요?', ['항상 relaxed에 장벽을 붙이는 쪽이에요', '정확히 요청한 order의 arch 정의가 첫 분기예요'], '정답은 두 번째예요. #if가 직접 형태, 그다음 #elif가 허용된 relaxed 보강이에요. 두 정의가 있다고 둘 다 실행하는 것은 아니에요.'), ('128이라는 API 이름이 생성되면 모든 CPU가 직접 128비트 명령을 지원하나요?', ['아니요. 해당 아키텍처의 실제 지원과 구현을 확인해야 해요', '네. 생성기가 하드웨어 명령을 새로 만들어 줘요'], '정답은 첫 번째예요. 코드의 이름과 하드웨어 기능은 달라요. 지원되지 않는 이름은 생성돼 있어도 실제 사용할 수 있는지 별도 확인이 필요해요.')]), 'os1607': ('담당자가 “처음 본 숫자는 5였어요”라고 알려 주면 내 예상 4와 비교해 교체 실패를 알 수 있어요. 실패하면 예상 메모도 5로 고쳐 다음 시도를 준비할 수 있어요.', '이전 값 반환 cmpxchg를 bool·예상 값 갱신 try로 바꾸는 원리를 이해합니다.', '대상 5·예상 4·새 값 9는 반환 false·대상 5·예상 5, 대상 5·예상 5·새 값 9는 반환 true·대상 9·예상 5로 적으세요.', ['cmpxchg는 예상 값과 같을 때 교체하고 관찰한 이전 숫자를 반환해요. try_cmpxchg는 교체 성공 여부를 참·거짓으로 반환하고, 실패하면 예상 메모를 실제 관찰값으로 고쳐요. 이 양식은 첫 기능으로 두 번째 기능을 만들어요.', '___op는 예상 메모 위치이고 ___o는 그 메모에 있던 값을 복사한 것이에요. ___r은 raw cmpxchg가 반환한 관찰값을 담아요. 위치와 복사한 숫자, 반환 숫자를 나누어 보면 긴 이름도 따라갈 수 있어요.', 'raw cmpxchg를 대상 위치, 기존 예상 ___o, 새 값으로 호출해요. 반환 ___r이 ___o와 다르면 비교 실패예요. 이때 *___op = ___r로 예상 메모를 고쳐요.', '대상이 5인데 예상이 4였다면 ___r=5, ___o=4예요. 둘이 달라서 대상은 5 그대로이고 예상 메모에 5를 적어요. 마지막 ___r == ___o는 거짓이므로 false를 반환해요.', '대상과 예상이 둘 다 5였다면 raw는 새 값 9를 저장하고 이전 5를 돌려줘요. ___r과 ___o가 같으므로 메모를 고치는 갈래는 건너뛰고 true예요. 성공할 때 예상 메모를 9로 바꾸는 규칙은 아니에요.', 'likely·unlikely는 조건 결과를 뒤집는 말이 아니라 최적화에 도움을 주는 힌트예요. 실제 성공 여부는 값의 일치로 결정돼요. 지역 변수를 쓴다고 대상과 메모의 수명이 자동 보장되지는 않으므로 올바른 저장 공간을 전달해야 해요.'], [('generic try의 비교가 실패하면 예상 메모에 무엇을 기록하나요?', ['무조건 넣으려던 새 값 new를 적어요', 'cmpxchg가 관찰해 반환한 이전 값 ___r을 적어요'], '정답은 두 번째예요. ___r != ___o일 때 *___op = ___r을 해요. 실패한 대상의 새 값이 아니라 실제로 관찰한 값을 다음 예상으로 쓰는 것이에요.'), ('이 변환에서 성공을 판단하는 비교는 무엇인가요?', ['관찰한 ___r과 기존 예상 ___o가 같은지예요', '관찰한 숫자가 무조건 1인지예요'], '정답은 첫 번째예요. 예상이 5이고 관찰도 5이면 성공이며 0끼리 같아도 성공일 수 있어요. 특정 숫자 1을 성공 표시로 반환하는 cmpxchg가 아니에요.')]), 'os1608': ('“비교하고 옛 값을 알려 주는 도구”가 있으면 그 답을 보고 성공 여부를 알려 주는 도구도 만들 수 있어요. 반드시 별도 try 명령이 있어야 하는 것은 아니에요.', 'native try 선택과 cmpxchg로 try를 구성하는 경로를 이해합니다.', '직접 arch try → relaxed try 보강 → full try 재사용 → raw cmpxchg로 변환의 후보를 적으세요.', ['gen_try_cmpxchg_order_fallback은 먼저 요청한 순서의 arch_try가 정의됐는지 확인하는 코드를 출력해요. native라는 말은 여기서 아키텍처가 해당 기능을 직접 제공하는 경로라는 뜻으로 읽으면 돼요.', '직접 경로가 없으면 요청 조건에 따라 relaxed try를 보강하거나 기본 full try를 재사용하는 후보를 확인해요. 모든 후보를 한 번에 실행하는 것이 아니라 컴파일 때 맞는 경로를 선택해요.', '이 try 경로들이 없으면 같은 order의 raw cmpxchg를 이용하는 변환 양식을 만들어요. 이전 값과 예상 값을 비교해 bool을 만들고, 실패하면 예상 메모를 갱신하는 앞 수업의 방법이에요.', '따라서 별도의 try 명령이 없다는 이유만으로 항상 try API를 만들 수 없는 것은 아니에요. 다만 기반 cmpxchg 자체는 지원돼야 해요. 없는 하드웨어 기능을 이름만으로 만들어 내는 것은 아니에요.', 'local·sync 경로의 gen_def_and_try_cmpxchg_fallback은 먼저 raw compare 이름을 arch compare에 연결해요. 이어서 arch try가 있으면 연결하고, 없으면 compare를 사용하는 try 변환을 만들어요. 이름 연결을 alias, 즉 별칭이라고 해요.', 'local·sync라는 다른 이름을 붙였다고 모든 순서·지원 조건이 같아지지는 않아요. 선택된 compare 경로의 약속을 유지하며 try의 반환 방식을 구성하는 것이에요. 생성 경로를 읽었다고 모든 폭과 CPU에서 실행 검증한 것은 아니에요.'], [('직접 try가 없어도 지원되는 compare 연산이 있으면 try를 구성할 수 있나요?', ['아니요. 모든 CPU에 별도의 try 명령이 반드시 있어야 해요', '네. 이전 값 비교와 예상 메모 갱신으로 구성할 수 있어요'], '정답은 두 번째예요. 마지막 대체 경로가 raw cmpxchg를 호출해 성공 bool과 실패 메모 갱신을 만들어요. 단, 기반 compare 연산이 실제로 지원돼야 해요.'), ('local·sync 도우미는 compare 이름 연결과 선택적인 try 변환을 함께 만드나요?', ['네. compare를 연결하고 직접 try가 없으면 변환을 만들어요', '아니요. 이름 글자만 적고 호출 연결은 만들지 않아요'], '정답은 첫 번째예요. define으로 compare를 연결하고 ifdef·else로 직접 try와 변환을 나눠요. 별칭과 대체 구현의 두 역할을 함께 보세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_397.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
